11	// Control-plane commands reference orgs and projects by their parent ULID in
12	// many places (repo create --project, project create --owner, grant org/project
13	// <id>, …). ULIDs are unfriendly to type, so these refs also accept a human
14	// name: looksLikeULID decides which form was given, and the resolveXRef helpers
15	// turn a name into its ULID via a list lookup. A ULID is always passed straight
16	// through with no network call, preserving the original behavior exactly.
17	
18	// looksLikeULID reports whether s has the shape of a ULID: 26 characters drawn
19	// from Crockford base32 (digits plus uppercase letters, excluding I, L, O, U).
20	// The check is shape-only and case-insensitive on the alphabet; it never hits
21	// the network. A name that happened to be 26 valid base32 characters would be
22	// misread as an id, but real org/project names don't take that form, and the
23	// user can always fall back to the explicit ULID.
24	func looksLikeULID(s string) bool {
25		if len(s) != 26 {
26			return false
27		}
28		for _, r := range strings.ToUpper(s) {
29			switch {
30			case r >= '0' && r <= '9':
31			case r >= 'A' && r <= 'Z' && r != 'I' && r != 'L' && r != 'O' && r != 'U':
32			default:
33				return false
34			}
35		}
36		return true
37	}
38	
39	// resolveOrgRef turns an org reference (ULID or name) into its ULID. A ULID is
40	// returned unchanged; a name is looked up against the caller's visible orgs.
41	func resolveOrgRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
42		if looksLikeULID(ref) {
43			return ref, nil
44		}
45		out, err := c.ListOrgs(ctx)
46		if err != nil {
47			return "", err
48		}
49		return pickOrg(out.Orgs, ref)
50	}
51	
52	// resolveAccountRef turns an account reference into its ULID. A ULID passes
53	// through unchanged; otherwise the ref is a provider-qualified handle (e.g.
54	// "github:alice") resolved via the control plane. We support github-backed
55	// user accounts today; other providers will resolve once they exist server-side.
56	func resolveAccountRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
57		if looksLikeULID(ref) {
58			return ref, nil
59		}
60		provider, handle, err := parseQualifiedHandle(ref)
61		if err != nil {
62			return "", err
63		}
64		id, err := c.ResolveHandle(ctx, coreapi.ResolveHandleParams{Provider: provider, Handle: handle})
65		if err != nil {
66			return "", err
67		}
68		return id.AccountId, nil
69	}
70	
71	// parseQualifiedHandle splits a provider-qualified handle like "github:alice"
72	// into its provider ("github") and handle ("alice"). Accounts are addressed by
73	// this friendly form; a value with no "provider:" prefix is rejected so the
74	// user gets a clear hint rather than a confusing lookup miss.
75	func parseQualifiedHandle(ref string) (provider, handle string, err error) {
76		provider, handle, ok := strings.Cut(ref, ":")
77		if !ok || provider == "" || handle == "" {
78			return "", "", fmt.Errorf("account %q must be a qualified handle like \"github:alice\" (or a ULID)", ref)
79		}
80		return provider, handle, nil
81	}
82	
83	// resolveProjectRef turns a project reference (ULID or name) into its ULID. A
84	// ULID is returned unchanged; a name is looked up via the server's exact-name
85	// filter (the same call `entire project list --name` uses).
86	func resolveProjectRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
87		if looksLikeULID(ref) {
88			return ref, nil
89		}
90		out, err := c.ListProjects(ctx, coreapi.ListProjectsParams{Name: coreapi.NewOptString(ref)})
91		if err != nil {
92			return "", err
93		}
94		return pickProject(out.Projects, ref)
95	}
96	
97	// pickOrg selects the single org named name. Org names are unique, so a name
98	// matches at most one org; zero matches is an error pointing at `org list`, and
99	// (defensively) multiple matches list the colliding ids so the user can fall
100	// back to a ULID.
101	func pickOrg(orgs []coreapi.Org, name string) (string, error) {
102		var matches []coreapi.Org
103		for _, o := range orgs {
104			if o.Name == name {
105				matches = append(matches, o)
106			}
107		}
108		switch len(matches) {
109		case 1:
110			return matches[0].ID, nil
111		case 0:
112			return "", fmt.Errorf("no org named %q (run `entire org list` to see names, or pass a ULID)", name)
113		default:
114			ids := make([]string, len(matches))
115			for i, o := range matches {
116				ids[i] = o.ID
117			}
118			return "", fmt.Errorf("org name %q is ambiguous (%s); pass a ULID instead", name, strings.Join(ids, ", "))
119		}
120	}
121	
122	// pickProject selects the single project named name. Project names are unique
123	// only within an owner, so a bare name can match several projects across
124	// different orgs/accounts; on ambiguity the candidates (id + owner) are listed
125	// so the user can pass the intended ULID. (We can't suggest re-scoping the
126	// failing command: resolveProjectRef's callers — repo create/list, grant
127	// project … — have no --org flag; only `entire project list` does.)
128	func pickProject(projects []coreapi.Project, name string) (string, error) {
129		var matches []coreapi.Project
130		for _, p := range projects {
131			if p.Name == name {
132				matches = append(matches, p)
133			}
134		}
135		switch len(matches) {
136		case 1:
137			return matches[0].ID, nil
138		case 0:
139			return "", fmt.Errorf("no project named %q (run `entire project list` to see names, or pass a ULID)", name)
140		default:
141			parts := make([]string, len(matches))
142			for i, p := range matches {
143				parts[i] = fmt.Sprintf("%s (owner %s)", p.ID, p.OwnerId)
144			}
145			return "", fmt.Errorf("project name %q is ambiguous (%s); pass the intended ULID (run `entire project list --org <org>` to find it)", name, strings.Join(parts, ", "))
146		}
147	}
148	
149	// filterProjectsByName narrows projects to exact name matches, returning all of
150	// them when name is empty. Used by `project list --org` to apply --name
151	// client-side, since the org-scoped list endpoint has no name parameter.
152	func filterProjectsByName(projects []coreapi.Project, name string) []coreapi.Project {
153		if name == "" {
154			return projects
155		}
156		var out []coreapi.Project
157		for _, p := range projects {
158			if p.Name == name {
159				out = append(out, p)
160			}
161		}
162		return out
163	}
