9	func TestLooksLikeULID(t *testing.T) {
10		t.Parallel()
11		tests := []struct {
12			in   string
13			want bool
14		}{
15			{in: "REDACTED", want: true}, // 26 chars, valid alphabet
16			{in: "REDACTED", want: true}, // lowercase accepted
17			{in: "acme", want: false},                      // short name
18			{in: "my-project", want: false},                // hyphen not in alphabet
19			{in: "", want: false},                          // empty
20			{in: "01J0ABCDEFGHJKMNPQRSTVWXY", want: false}, // 25 chars
21			{in: "REDACTED", want: false},
22			{in: "REDACTED", want: false}, // contains I
23			{in: "REDACTED", want: false}, // contains L
24			{in: "REDACTED", want: false}, // contains O
25			{in: "REDACTED", want: false}, // contains U
26		}
27		for _, tt := range tests {
28			t.Run(tt.in, func(t *testing.T) {
29				t.Parallel()
30				if got := looksLikeULID(tt.in); got != tt.want {
31					t.Errorf("looksLikeULID(%q) = %v, want %v", tt.in, got, tt.want)
32				}
33			})
34		}
35	}
